cards.solution:
const API = "https://api.toko.contoh";
function buatUrl(path, params) {
  const url = new URL(path, API);
  for (const [nama, nilai] of Object.entries(params)) {
    url.searchParams.set(nama, nilai);
  }
  return url;
}
const url = buatUrl("/products", { category: "minuman", limit: 1 });
console.log(url.toString());
const produk = await (await fetch(url)).json();
console.log(produk.map((p) => p.name).join(", "));
